class Solution {
public:
    int countSubstrings(string s) {
        int n = s.size();
        int ans = 0;
        // there are 2*n-1 possible centres (character and gap)
        for (int centre = 0; centre < 2 * n - 1; ++centre) {
            int left = centre / 2;
            int right = left + centre % 2;
            while (left >= 0 && right < n && s[left] == s[right]) {
                ++ans;
                --left;
                ++right;
            }
        }
        return ans;
    }
};
